108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        String address = addressNormalizer.normalize(owner.getAddress());
114	        if (address.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        owner.setAddress(address);
118	        String telephone = toE164(owner.getTelephone());
119	        if (telephone == null) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setTelephone(telephone);
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        if (isTelephoneInUse(telephone)) {
127	            return new ResponseEntity<>(HttpStatus.CONFLICT);
128	        }
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
131	            return new ResponseEntity<>(HttpStatus.CONFLICT);
132	        }
133	        if (sharesHousehold) {
134	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
135	        }
136	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
137	        this.clinicService.saveOwner(owner);
138	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
139	        headers.setLocation(UriComponentsBuilder.newInstance()
140	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
141	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
142	    }
143	
144	    /**
145	     * Build the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}
146	     * where LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
147	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
148	     * (e.g. {@code 'SMI-0007'}).
149	     */
150	    private String nextCustomerCode(String lastName) {
151	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
152	        int sequence = this.clinicService.findAllOwners().size() + 1;
153	        return String.format("%s-%04d", last3, sequence);
154	    }
155	
156	    /**
157	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
158	     * cannot form a valid E.164 number.
159	     *
160	     * <p>A leading '+' and country code are kept when present; otherwise country code
161	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
162	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
163	     * carry 8 to 15 digits after the '+'.
164	     */
165	    private String toE164(String telephone) {
166	        if (telephone == null) {
167	            return null;
168	        }
169	        boolean hasCountryCode = telephone.trim().startsWith("+");
170	        String digits = telephone.replaceAll("\\D", "");
171	        String e164;
172	        if (hasCountryCode) {
173	            e164 = digits;
174	        } else {
175	            if (digits.startsWith("0")) {
176	                digits = digits.substring(1);
177	            }
178	            e164 = "61" + digits;
179	        }
180	        if (e164.length() < 8 || e164.length() > 15) {
181	            return null;
182	        }
183	        return "+" + e164;
184	    }
185	
186	    /**
187	     * Whether any existing owner already holds the given telephone number. Both the
188	     * candidate and each stored number are compared in E.164 form, so the check does not
189	     * depend on how each was originally formatted.
190	     */
191	    private boolean isTelephoneInUse(String telephone) {
192	        return this.clinicService.findAllOwners().stream()
193	            .map(Owner::getTelephone)
194	            .filter(Objects::nonNull)
195	            .map(this::toE164)
196	            .filter(Objects::nonNull)
197	            .anyMatch(telephone::equals);
198	    }
199	
200	    /**
201	     * Whether any existing owner already shares a household with the candidate, i.e. has both
202	     * the same lastName and the same address. Both fields are compared case-insensitively and
203	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
204	     * trimmed), so the check does not depend on casing or spacing.
205	     */
206	    private boolean isHouseholdInUse(String lastName, String address) {
207	        String candidateLastName = normalizeName(lastName);
208	        String candidateAddress = addressNormalizer.normalize(address);
209	        return this.clinicService.findAllOwners().stream()
210	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
211	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
212	    }
213	
214	    /**
215	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
216	     * to a single space and lower-case. A null value normalizes to the empty string.
217	     */
218	    private String normalizeName(String value) {
219	        if (value == null) {
220	            return "";
221	        }
222	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
223	    }
224	
225	    /**
226	     * A stable shared identifier for the household formed by a given lastName and address.
227	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
228	     * lastName and address, so every owner sharing the same household is assigned the same
229	     * value regardless of the order in which they are created. Formatted as the first 12
230	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
231	     */
232	    private String householdId(String lastName, String address) {
233	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
234	        try {
235	            byte[] digest = MessageDigest.getInstance("SHA-256")
236	                .digest(key.getBytes(StandardCharsets.UTF_8));
237	            StringBuilder sb = new StringBuilder(digest.length * 2);
238	            for (byte b : digest) {
239	                sb.append(String.format("%02x", b));
240	            }
241	            return sb.substring(0, 12).toUpperCase();
242	        }
243	        catch (NoSuchAlgorithmException e) {
244	            throw new IllegalStateException("SHA-256 not available", e);
245	        }
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
